const packName = itemId => {
  let name;
  if (itemId === 1001) {
    name = "Magnet";
  } else if (itemId === 1002) {
    name = "Double Points Card";
  } else if (itemId === 1003) {
    name = "Revival Card";
  } else if (itemId === 1004) {
    name = "Treasure Chest";
  } else if (itemId === 1101) {
    name = "Room Hour Card";
  } else if (itemId === 1102) {
    name = "Room Day Card";
  } else if (itemId === 1103) {
    name = "Room Weekly Card";
  } else if (itemId === 1201) {
    name = "Python essence";
  } else if (itemId === 1202) {
    name = "Extended scroll";
  } else if (itemId === 1203) {
    name = "Lightning Serum";
  } else if (itemId === 1204) {
    name = "Divine speed potion";
  } else if (itemId === 1205) {
    name = "The fruit of omnivision";
  } else if (itemId === 1206) {
    name = "Energy Potion";
  } else if (itemId === 1207) {
    name = "Honor Token (Coupon)";
  } else if (itemId === 1208) {
    name = "Treasure Box 1";
  } else if (itemId === 10001) {
    name = "Diamonds";
  } else if (itemId === 10002) {
    name = "Experience";
  } else if (itemId === 10003) {
    name = "USDT";
  } else if (itemId === 10004) {
    name = "Energy";
  }
  return name;
};
